    for (int row = 0; row < 5; ++row) {
        for (int col = 0; col < 10; ++col) {
            bricks.push_back(Brick(100 + col * 70, 50 + row * 20, 50, 20, sf::Color::Red));
        }
    }

    Score score(10, 10, 20, font);

    sf::Clock clock;
    bool gameRunning = true;
    bool gameOver = false;

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
