        if (!gameRunning) {
            continue;
        }

        if (gameOver) {
            window.clear(sf::Color::Black);
            sf::Text text;
            text.setFont(font);
            text.setString("Game Over");
            text.setCharacterSize(48);
            text.setColor(sf::Color::White);
            text.setPosition(350, 250);
            window.draw(text);
            window.display();
            continue;
        }

        window.clear(sf::Color::Black);

        float deltaTime = clock.restart().asSeconds();

        paddle.move(0);
        for (auto &ball : balls) {
            ball.update();
            if (ball.isOutOfBounds(window)) {
                ball = Ball(400, 300, 10);
            }
        }

        for (auto &brick : bricks) {
            brick.draw(window);
        }

        paddle.draw(window);
        for (auto &ball : balls) {
            ball.draw(window);
        }

        score.draw(window);

        window.display();
    }

