 draw() {
  background(pink);
  noStroke();
  let gridSize = 20;
  let cellSize = width / gridSize;

  for (let i = 0; i < gridSize; i++){
    for (let j = 0; j < gridSize; j++){
      let x = i * cellSize;
      let y = j * cellSize;

      let c = random(colors);
      let size = random(cellSize*0.5, cellSize*1.5);
      let offset = random(-size/2, size/2);
      fill(c);

      // create abstract shapes
      if(random() < 0.3) {
        ellipse(x + cellSize/2, y + cellSize/2, size);
      } else if(random() < 0.6) {
        rect(x + offset, y + offset, size, size);
      } else {
        let x1 = x + offset;
        let y1 = y + offset;
        let x2 = x + size + offset;
        let y2 = y + size + offset;
        triangle(x1, y1, x2, y1, x1, y2);
      }

      // add lines to break grid
      if(random() < 0.3) {
        strokeWeight(2);
        stroke(255);
        line(x, y, x + cellSize, y + cellSize);
      }
    }
  }
}
